ee:variables.ee:set-variable:
%dw 2.0
output application/java
---
(vars.vReply.step ++ ":" ++ vars.vReply.outcome) match {
	case "PAYMENT:APPROVED" -> { status: "RUNNING", nextStep: "STOCK" }
	case "PAYMENT:DECLINED" -> { status: "FAILED", nextStep: null }
	case "STOCK:RESERVED" -> { status: "RUNNING", nextStep: "INVOICE" }
	case "STOCK:UNAVAILABLE" -> { status: "COMPENSATING", nextStep: "REFUND" }
	case "INVOICE:ISSUED" -> { status: "COMPLETED", nextStep: null }
	case "REFUND:REFUNDED" -> { status: "CANCELLED", nextStep: null }
	else -> null
}
